IF OBJECT_ID(N'tsaat.fn_kpi_stable_hash') IS NOT NULL THROW 52000, 'Retired routine remains: fn_kpi_stable_hash', 1;
IF NOT EXISTS(SELECT 1 FROM tsaat.cmdb_attribute_definition) THROW 52000, 'CMDB catalogue is empty.', 1;
IF NOT EXISTS(SELECT 1 FROM tsaat.persona_settings_version) THROW 52000, 'Persona settings are empty.', 1;
IF NOT EXISTS(SELECT 1 FROM tsaat.discovery_tools_settings_version) THROW 52000, 'Discovery settings are empty.', 1;
IF (SELECT COUNT(*) FROM tsaat.dataset_snapshot)<5 OR (SELECT DATEDIFF(day,MIN(snapshot_date),MAX(snapshot_date)) FROM tsaat.dataset_snapshot)<28
 THROW 52000, 'At least four complete weeks of evidence are required.', 1;
IF EXISTS(SELECT 1 FROM (SELECT snapshot_date,LAG(snapshot_date) OVER(ORDER BY snapshot_date) previous_date FROM tsaat.dataset_snapshot) d WHERE DATEDIFF(day,previous_date,snapshot_date)<>7)
 THROW 52000, 'Evidence snapshots must be weekly.', 1;
IF EXISTS(SELECT 1 FROM tsaat.dataset_snapshot s WHERE NOT EXISTS(SELECT 1 FROM tsaat.asset a WHERE a.snapshot_id=s.snapshot_id))
 THROW 52000, 'An inventory snapshot is empty.', 1;
IF EXISTS(SELECT 1 FROM tsaat.asset_vulnerability v JOIN tsaat.dataset_snapshot s ON s.snapshot_id=v.snapshot_id WHERE v.detected_date>s.snapshot_date OR CONVERT(date,v.captured_at)>s.snapshot_date)
 THROW 52000, 'Vulnerability evidence is newer than its snapshot.', 1;
IF EXISTS(SELECT 1 FROM sys.foreign_keys WHERE schema_id=SCHEMA_ID(N'tsaat') AND (is_disabled=1 OR is_not_trusted=1))
 THROW 52000, 'Inventory relationships must have enabled, trusted foreign keys.', 1;
DECLARE @snapshot bigint;
DECLARE checks CURSOR LOCAL FAST_FORWARD FOR SELECT snapshot_id FROM tsaat.dataset_snapshot ORDER BY snapshot_id;
OPEN checks; FETCH NEXT FROM checks INTO @snapshot;
WHILE @@FETCH_STATUS=0 BEGIN
 EXEC tsaat.usp_evaluate_discovery_coverage_snapshot @snapshot_id=@snapshot;
 FETCH NEXT FROM checks INTO @snapshot;
END;
CLOSE checks; DEALLOCATE checks;
PRINT 'Inventory v2 schema and weekly evidence validation passed.';
